fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since `a.len() == b.len()` is recommended,
    // we assume lengths are equal and iterate accordingly.
    let len = a.len();
    let mut result = Vec::with_capacity(len);
    let mut i = 0;
    while i < len {
        // Compare a[i] and b[i] as i32 values to avoid overflow issues.
        result.push((a[i] as i32) > (b[i] as i32));
        i += 1;
    }
    result
}